The issue is that `add_dye_each` itself must be replicated (once per tube, in series after the shared spin), not triggered per-instance from a non-replicated step. Let me fix this:

```json
{
  "schemaVersion": "0.3.0-alpha",
  "programId": "colony-pcr-screen-8",
  "name": "Colony PCR Screen with Diagnostic Gel",
  "description": "Eight clones screened by PCR and run on a single agarose gel. Gel prep overlaps with cycling.",
  "environmentType": "laboratory",
  "actors": 1,
  "tracks": [
    {
      "trackId": "reactions",
      "name": "PCR Reactions",
      "steps": [
        {
          "stepId": "thaw_reagents",
          "name": "Thaw primers, dNTPs, buffer on ice",
          "task": "operator",
          "duration": { "type": "fixed", "seconds": 900 },
          "startTrigger": { "type": "programStart" }
        },
        {
          "stepId": "master_mix",
          "name": "Assemble master mix (9× reactions)",
          "task": "operator",
          "duration": { "type": "fixed", "seconds": 600 },
          "startTrigger": { "type": "afterStep", "stepId": "thaw_reagents" }
        },
        {
          "stepId": "aliquot_spin",
          "name": "Aliquot into strip tube, add colony, spin",
          "task": "microcentrifuge",
          "duration": { "type": "fixed", "seconds": 300 },
          "replicates": { "count": 8, "mode": "serial" },
          "startTrigger": { "type": "afterStep", "stepId": "master_mix" }
        },
        {
          "stepId": "load_thermocycler",
          "name": "Load strip tubes into thermocycler",
          "task": "thermocycler",
          "duration": { "type": "fixed", "seconds": 180 },
          "startTrigger": { "type": "afterStep", "stepId": "aliquot_spin", "instances": "all" }
        },
        {
          "stepId": "cycle",
          "name": "Run PCR program (95→35×(95/58/72)→72)",
          "task": "thermocycler",
          "duration": { "type": "fixed", "seconds": 6600 },
          "startTrigger": { "type": "afterStep", "stepId": "load_thermocycler" }
        },
        {
          "stepId": "spin_after_cycle",
          "name": "Spin down PCR tubes",
          "task": "microcentrifuge",
          "duration": { "type": "fixed", "seconds": 300 },
          "startTrigger": { "type": "afterStep", "stepId": "cycle" }
        },
        {
          "stepId": "add_dye_each",
          "name": "Add 5 µL loading dye to tube",
          "task": "operator",
          "duration": { "type": "fixed", "seconds": 300 },
          "replicates": { "count": 8, "mode": "serial" },
          "startTrigger": { "type": "afterStep", "stepId": "spin_after_cycle" }
        }
      ]
    },
    {
      "trackId": "gel_prep",
      "name": "Gel Preparation",
      "steps": [
        {
          "stepId": "microwave_agarose",
          "name": "Weigh agarose, add TAE, microwave 3 min",
          "task": "microwave",
          "duration": { "type": "fixed", "seconds": 180 },
          "startTrigger": { "type": "programStartOffset", "offsetSeconds": 1500 }
        },
        {
          "stepId": "cool_gel",
          "name": "Cool flask on bench until comfortable",
          "task": "operator",
          "duration": { "type": "fixed", "seconds": 720 },
          "startTrigger": { "type": "afterStep", "stepId": "microwave_agarose" }
        },
        {
          "stepId": "stain_pour_comb",
          "name": "Add stain, pour gel, seat comb",
          "task": "operator",
          "duration": { "type": "fixed", "seconds": 180 },
          "startTrigger": { "type": "afterStep", "stepId": "cool_gel" }
        },
        {
          "stepId": "gel_set",
          "name": "Gel sets at room temperature",
          "task": "gel_rig",
          "duration": { "type": "fixed", "seconds": 2100 },
          "startTrigger": { "type": "afterStep", "stepId": "stain_pour_comb" }
        },
        {
          "stepId": "remove_comb_rig",
          "name": "Remove comb, place gel in rig with TAE",
          "task": "operator",
          "duration": { "type": "fixed", "seconds": 120 },
          "startTrigger": { "type": "afterStep", "stepId": "gel_set" }
        }
      ]
    },
    {
      "trackId": "ladder",
      "name": "Ladder Prep",
      "steps": [
        {
          "stepId": "thaw_ladder",
          "name": "Thaw 100 bp ladder, mix with 6× dye",
          "task": "operator",
          "duration": { "type": "fixed", "seconds": 300 },
          "startTrigger": { "type": "programStartOffset", "offsetSeconds": 6000 }
        }
      ]
    },
    {
      "trackId": "load_run_image",
      "name": "Load, Run & Image",
      "steps": [
        {
          "stepId": "load_gel",
          "name": "Load 10 µL per well + 5 µL ladder",
          "task": "operator",
          "duration": { "type": "fixed", "seconds": 480 },
          "startTrigger": {
            "type": "compound",
            "logic": "all",
            "triggers": [
              { "type": "afterStep", "stepId": "remove_comb_rig" },
              { "type": "afterStep", "stepId": "add_dye_each", "instances": "all" },
              { "type": "afterStep", "stepId": "thaw_ladder" }
            ]
          }
        },
        {
          "stepId": "run_gel",
          "name": "Run gel at 120 V for 40 min",
          "task": "gel_rig",
          "duration": { "type": "fixed", "seconds": 2400 },
          "startTrigger": { "type": "afterStep", "stepId": "load_gel" }
        },
        {
          "stepId": "image",
          "name": "Image on transilluminator",
          "task": "transilluminator",
          "duration": { "type": "fixed", "seconds": 300 },
          "startTrigger": { "type": "afterStep", "stepId": "run_gel" }
        },
        {
          "stepId": "record",
          "name": "Record clones with insert",
          "task": "operator",
          "duration": { "type": "fixed", "seconds": 600 },
          "startTrigger": { "type": "afterStep", "stepId": "image" }
        }
      ]
    }
  ],
  "resourceConstraints": [
    { "task": "thermocycler", "maxConcurrent": 1 },
    { "task": "microcentrifuge", "maxConcurrent": 1 },
    { "task": "microwave", "maxConcurrent": 1 },
    { "task": "gel_rig", "maxConcurrent": 1 },
    { "task": "transilluminator", "maxConcurrent": 1 },
    { "task": "operator", "maxConcurrent": 1 }
  ],
  "metadata": {
    "protocolType": "PCR screening + gel electrophoresis",
    "samples": 8,
    "sourceDescription": "Colony PCR screen with diagnostic gel for 8 clones"
  }
}
```

**Fix:** `add_dye_each` now declares `replicates: {count: 8, mode: "serial"}` so that it is itself replicated (one dye addition per tube, serially). The `load_gel` step now correctly references it with `instances: "all"` (the barrier that waits for all eight dye steps to complete).
